  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}
    # Build edges with canonical ordering
    edges = []
    seen = set()
    for a, b, d in distances:
        if a == b:
            continue
        u, v = (a, b) if a < b else (b, a)
        key = (u, v)
        if key in seen:
            continue
        seen.add(key)
        w = max(core_dist[u], core_dist[v], d)
        edges.append((w, u, v))
    # Sort: primary by weight, secondary by node ids
    edges.sort()
    # Union-Find structure (dicts)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is not connected; cannot form a spanning tree')
    return {'mst_edges': mst_edges, 'total_weight': total}
